export class InputController {
    constructor() {
        this.keys = {
            left: false,
            right: false,
            fire: false
        };

        this.gamepadIndex = -1;

        this.setupKeyboardListeners();
        this.setupGamepadListeners();
    }

    setupKeyboardListeners() {
        window.addEventListener('keydown', (event) => {
            switch(event.code) {
                case 'ArrowLeft':
                case 'KeyA':
                    this.keys.left = true;
                    break;
                case 'ArrowRight':
                case 'KeyD':
                    this.keys.right = true;
                    break;
                case 'Space':
                    this.keys.fire = true;
                    break;
            }
        });

        window.addEventListener('keyup', (event) => {
            switch(event.code) {
                case 'ArrowLeft':
                case 'KeyA':
                    this.keys.left = false;
                    break;
                case 'ArrowRight':
                case 'KeyD':
                    this.keys.right = false;
                    break;
                case 'Space':
                    this.keys.fire = false;
                    break;
            }
        });
    }

    setupGamepadListeners() {
        window.addEventListener('gamepadconnected', (event) => {
            console.log(`Gamepad connected at index ${event.gamepad.index}: ${event.gamepad.id}`);
            this.gamepadIndex = event.gamepad.index;
        });

        window.addEventListener('gamepaddisconnected', (event) => {
            if (this.gamepadIndex === event.gamepad.index) {
                console.log(`Gamepad disconnected at index ${event.gamepad.index}`);
                this.gamepadIndex = -1;
            }
        });
    }

    update() {
        // Check gamepad input
        if (this.gamepadIndex !== -1) {
            const gamepad = navigator.getGamepads()[this.gamepadIndex];
            if (gamepad) {
                // Left stick X axis for movement (-1 to 1)
                const leftStickX = gamepad.axes[0] || 0;
                if (leftStickX < -0.5) {
                    this.keys.left = true;
                    this.keys.right = false;
                } else if (leftStickX > 0.5) {
                    this.keys.right = true;
                    this.keys.left = false;
                } else {
                    this.keys.left = false;
                    this.keys.right = false;
                }

                // Button 0 (usually A/cross) or trigger for fire
                const isFirePressed = gamepad.buttons[0]?.pressed || gamepad.buttons[14]?.pressed || gamepad.buttons[15]?.pressed;
                this.keys.fire = isFirePressed;
            }
        }

        return { ...this.keys };
    }

    isLeftPressed() {
        return this.keys.left;
    }

    isRightPressed() {
        return this.keys.right;
    }

    isFirePressed() {
        return this.keys.fire;
    }
}
