import * as THREE from 'three';
import { ObjectPool } from '../pooling/ObjectPool.js';

export class ParticleManager {
    constructor(scene, maxParticles = 500) {
        this.scene = scene;
        this.maxParticles = maxParticles;
        this.particles = [];
        this.activeCount = 0;

        // Particle geometry and material (shared for performance)
        const particleGeometry = new THREE.SphereGeometry(0.1, 8, 8);
        this.particleMaterial = new THREE.MeshStandardMaterial({
            color: 0xffffff,
            emissive: 0xffffff,
            emissiveIntensity: 2,
            transparent: true,
            opacity: 1
        });

        this.pool = new ObjectPool(
            () => {
                const mesh = new THREE.Mesh(particleGeometry, this.particleMaterial.clone());
                mesh.visible = false;
                return mesh;
            },
            (particle) => {
                particle.position.set(0, 0, 0);
                particle.velocity = new THREE.Vector3(0, 0, 0);
                particle.life = 0;
                particle.maxLife = 1;
                particle.mesh.visible = false;
            }
        );

        // Pre-warm the pool
        for (let i = 0; i < maxParticles; i++) {
            const particle = this.pool.acquire();
            this.particles.push(particle);
        }
    }

    spawnParticle(position, color, velocity, lifeSpan) {
        if (this.activeCount >= this.maxParticles) {
            return null;
        }

        const particle = this.pool.acquire();
        if (!particle) {
            return null;
        }

        particle.mesh.position.copy(position);
        particle.velocity.copy(velocity);
        particle.life = lifeSpan;
        particle.maxLife = lifeSpan;

        // Update material color and emissive properties
        const colorVec = new THREE.Color(color);
        particle.mesh.material.color.copy(colorVec);
        particle.mesh.material.emissive.copy(colorVec);
        particle.mesh.visible = true;

        this.scene.add(particle.mesh);
        this.activeCount++;

        return particle;
    }

    update(deltaTime) {
        for (let i = this.particles.length - 1; i >= 0; i--) {
            const particle = this.particles[i];

            if (!particle.mesh.visible) {
                continue;
            }

            particle.life -= deltaTime;

            if (particle.life <= 0) {
                // Remove from scene and return to pool
                this.scene.remove(particle.mesh);
                particle.mesh.material.dispose();
                this.pool.release(particle.mesh);

                // Remove from active particles array
                this.particles.splice(i, 1);
                this.activeCount--;
            } else {
                // Update position
                const lifeRatio = particle.life / particle.maxLife;
                particle.mesh.position.add(
                    particle.velocity.clone().multiplyScalar(deltaTime)
                );
                particle.mesh.material.opacity = lifeRatio;
                particle.mesh.scale.setScalar(lifeRatio);
            }
        }
    }

    spawnBurst(position, color, count, speedRange = [2, 5], lifeSpan = 0.5) {
        for (let i = 0; i < count; i++) {
            const velocity = new THREE.Vector3(
                (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 2,
                (Math.random() - 0.5) * 2
            ).normalize().multiplyScalar(
                speedRange[0] + Math.random() * (speedRange[1] - speedRange[0])
            );

            this.spawnParticle(position, color, velocity, lifeSpan);
        }
    }

    cleanup() {
        for (const particle of this.particles) {
            if (particle.mesh.visible) {
                this.scene.remove(particle.mesh);
                particle.mesh.material.dispose();
            }
        }
        this.particles = [];
        this.activeCount = 0;
    }
}
