export class CameraShake {
    constructor(camera) {
        this.camera = camera;
        this.originalPosition = camera.position.clone();
        this.intensity = 0;
        this.decayRate = 0.95;
        this.isActive = false;
    }

    shake(intensity, duration = 0.3) {
        this.intensity = intensity;
        this.isActive = true;
        this.decayDuration = duration;
        this.startTime = performance.now();
    }

    update(deltaTime) {
        if (!this.isActive || this.intensity <= 0.01) {
            this.isActive = false;
            this.intensity = 0;
            this.camera.position.copy(this.originalPosition);
            return;
        }

        const elapsed = (performance.now() - this.startTime) / 1000;
        if (elapsed >= this.decayDuration) {
            this.isActive = false;
            this.intensity = 0;
            this.camera.position.copy(this.originalPosition);
            return;
        }

        // Decaying intensity
        this.intensity *= this.decayRate;

        // Random offset
        const offsetX = (Math.random() - 0.5) * this.intensity;
        const offsetY = (Math.random() - 0.5) * this.intensity;
        const offsetZ = (Math.random() - 0.5) * this.intensity * 0.5;

        this.camera.position.set(
            this.originalPosition.x + offsetX,
            this.originalPosition.y + offsetY,
            this.originalPosition.z + offsetZ
        );
    }

    reset() {
        this.isActive = false;
        this.intensity = 0;
        this.camera.position.copy(this.originalPosition);
    }
}
