export class HitStop {
    constructor() {
        this.isFrozen = false;
        this.freezeDuration = 0;
        this.elapsedTime = 0;
        this.targetTimescale = 1.0;
        this.currentTimescale = 1.0;
    }

    trigger(durationFrames, targetFPS = 60) {
        this.isFrozen = true;
        this.freezeDuration = durationFrames / targetFPS;
        this.elapsedTime = 0;
        this.targetTimescale = 0.0;
    }

    update(deltaTime) {
        if (this.isFrozen) {
            this.elapsedTime += deltaTime;

            if (this.elapsedTime >= this.freezeDuration) {
                this.isFrozen = false;
                this.currentTimescale = 1.0;
            } else {
                // Smooth transition to 0 and back to 1
                const progress = this.elapsedTime / this.freezeDuration;
                if (progress < 0.5) {
                    this.currentTimescale = 1.0 - (progress * 2); // 1 to 0
                } else {
                    this.currentTimescale = (progress - 0.5) * 2; // 0 to 1
                }
            }
        } else {
            // Smooth return to 1.0
            this.currentTimescale += (1.0 - this.currentTimescale) * 0.2;
        }

        return this.currentTimescale;
    }

    isCurrentlyFrozen() {
        return this.isFrozen || this.currentTimescale < 0.1;
    }
}
