import * as THREE from 'three';

export class MotionTrails {
    constructor(scene) {
        this.scene = scene;
        this.trails = [];

        // Trail geometry and material
        this.trailGeometry = new THREE.CylinderGeometry(0.05, 0.05, 1, 8);
        this.trailMaterial = new THREE.MeshStandardMaterial({
            color: 0x00ffff,
            emissive: 0x00ffff,
            emissiveIntensity: 2,
            transparent: true,
            opacity: 0.8
        });
    }

    createTrail(startPos, endPos, color = 0x00ffff, duration = 0.3) {
        const direction = new THREE.Vector3().subVectors(endPos, startPos).normalize();
        const distance = startPos.distanceTo(endPos);

        if (distance < 0.5) return null;

        const trailMesh = new THREE.Mesh(this.trailGeometry, this.trailMaterial.clone());

        // Set material color
        const colorVec = new THREE.Color(color);
        trailMesh.material.color.copy(colorVec);
        trailMesh.material.emissive.copy(colorVec);

        // Position and rotate
        trailMesh.position.copy(startPos).add(endPos).multiplyScalar(0.5);
        trailMesh.lookAt(endPos);
        trailMesh.rotateX(Math.PI / 2);

        // Scale to match distance
        const scaleZ = distance;
        trailMesh.scale.set(1, 1, scaleZ);

        this.scene.add(trailMesh);

        const trail = {
            mesh: trailMesh,
            createdAt: performance.now(),
            duration: duration
        };

        this.trails.push(trail);
        return trail;
    }

    update(deltaTime) {
        const now = performance.now();

        for (let i = this.trails.length - 1; i >= 0; i--) {
            const trail = this.trails[i];
            const age = (now - trail.createdAt) / 1000;

            if (age >= trail.duration) {
                // Remove trail
                this.scene.remove(trail.mesh);
                trail.mesh.geometry.dispose();
                trail.mesh.material.dispose();
                this.trails.splice(i, 1);
            } else {
                // Fade out
                const lifeRatio = 1 - (age / trail.duration);
                trail.mesh.material.opacity = lifeRatio * 0.8;
            }
        }
    }

    cleanup() {
        for (const trail of this.trails) {
            this.scene.remove(trail.mesh);
            trail.mesh.geometry.dispose();
            trail.mesh.material.dispose();
        }
        this.trails = [];
    }
}
