        const ringMesh = new THREE.Mesh(this.ringGeometry, this.ringMaterial.clone());

        const colorVec = new THREE.Color(color);
        ringMesh.material.color.copy(colorVec);
        ringMesh.material.emissive.copy(colorVec);

        ringMesh.position.copy(position);
        ringMesh.rotation.x = Math.PI / 2;

        // Scale to initial radius
        const scale = initialRadius;
        ringMesh.scale.set(scale, scale, 1);

        this.scene.add(ringMesh);

        const ring = {
            mesh: ringMesh,
            createdAt: performance.now(),
            initialRadius: initialRadius,
            maxRadius: maxRadius,
            duration: duration,
            color: color
        };

        this.rings.push(ring);
        return ring;
    }

    update(deltaTime) {
        const now = performance.now();

        for (let i = this.rings.length - 1; i >= 0; i--) {
            const ring = this.rings[i];
            const age = (now - ring.createdAt) / 1000;

            if (age >= ring.duration) {
                // Remove ring
                this.scene.remove(ring.mesh);
                ring.mesh.material.dispose();
                this.rings.splice(i, 1);
            } else {
                // Expand and fade
                const progress = age / ring.duration;
                const currentRadius = ring.initialRadius + (ring.maxRadius - ring.initialRadius) * progress;

                ring.mesh.scale.set(currentRadius, currentRadius, 1);
                ring.mesh.material.opacity = 1 - progress;
            }
        }
    }

    cleanup() {
        for (const ring of this.rings) {
            this.scene.remove(ring.mesh);
            ring.mesh.material.dispose();
        }
        this.rings = [];
    }
}
