        this.startScreen = document.getElementById('start-screen');

        this.currentScore = 0;
        this.currentLives = 3;
        this.waveStatus = 'Ready';
    }

    initialize() {
        this.scoreUI.style.display = 'block';
        this.livesUI.style.display = 'block';
        this.waveUI.style.display = 'block';
        if (this.startScreen) {
            this.startScreen.style.display = 'none';
        }

        this.updateScore(0);
        this.updateLives(3);
        this.updateWaveStatus('Ready');
    }

    updateScore(score) {
        this.currentScore = score;
        if (this.scoreElement) {
            this.scoreElement.textContent = this.currentScore.toString();
        }
    }

    updateLives(lives) {
        this.currentLives = lives;
        if (this.livesElement) {
            this.livesElement.textContent = this.currentLives.toString();
        }
    }

    updateWaveStatus(status) {
        this.waveStatus = status;
        if (this.waveElement) {
            this.waveElement.textContent = this.waveStatus;
        }
    }

    showFloatingScore(position3D, camera, renderer, points) {
        const floatingEl = document.createElement('div');
        floatingEl.className = 'floating-score';
        floatingEl.textContent = `+${points}`;

        // Project 3D position to 2D screen coordinates
        const vector = new THREE.Vector3(position3D.x, position3D.y, position3D.z);
        vector.project(camera);

        const x = (vector.x * .5 + .5) * window.innerWidth;
        const y = (-(vector.y * .5) + .5) * window.innerHeight;

        floatingEl.style.left = `${x}px`;
        floatingEl.style.top = `${y}px`;

        document.body.appendChild(floatingEl);

        setTimeout(() => {
            if (floatingEl.parentNode) {
                floatingEl.parentNode.removeChild(floatingEl);
            }
        }, 1000);
    }

    showStartScreen() {
        if (this.startScreen) {
            this.startScreen.style.display = 'flex';
        }
        if (this.scoreUI) this.scoreUI.style.display = 'none';
        if (this.livesUI) this.livesUI.style.display = 'none';
        if (this.waveUI) this.waveUI.style.display = 'none';
    }

    hideStartScreen() {
        if (this.startScreen) {
            this.startScreen.style.display = 'none';
        }
    }
}
